import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n, sqrt_n

primes_to_check = [p for p in range(37, 101) if is_prime(p)]
results = []

print("Starting systematic search for primes p in [37, 100].")

for p in primes_to_check:
    # Calculate the discriminant D = 4p^3 - 3
    D = 4 * (p**3) - 3

    # Check if D is a perfect square k^2
    is_square, k = is_perfect_square(D)

    if is_square:
        # Determine q = (1 + k) / 2
        # Since X = 2q - 1, and X must be positive for q > 0, we take k > 0.
        # Since D is positive, k is real and positive.

        # Check if 1 + k is even (i.e., k is odd)
        if (1 + k) % 2 == 0:
            q = (1 + k) // 2

            # Verify if q is a prime and q != p
            if is_prime(q) and q != p:
                results.append((p, q, D, k))

print("\nSearch complete.")
if results:
    print("Found new solutions:")
    for p, q, D, k in results:
        print(f"p={p}, q={q}. Discriminant D={D} = {k}^2. Verified.")
else:
    print("No new solutions found in the range p=37 to p=100.")
